import styled from "styled-components";
import React, {useRef, useState, useEffect} from "react";
import "../../styles/WordButton.css";

export const WordButton = ({backgroundColor = null, label, size, onClick}) => {
	const [isActive, setIsActive] = useState(false);
	const toggle = () => {
		setIsActive(!isActive);
	};
	return (
		<button
			type="button"
			className={`word-button ${isActive ? "word-button word-button--primary" : "word-button word-button--secondary"}`}
			onClick={() => {
				console.log(label);
				toggle();
				console.log(isActive);
			}}
		>
			{label}
		</button>
	);
};

export default WordButton;
